"""Inspectors module."""

from typing import Any, Callable
from abc import ABC, abstractmethod
from robot.libraries.BuiltIn import BuiltIn
from robot.running.context import EXECUTION_CONTEXTS
from taf.rfrl.utilities.parsers.pcap_checker.utils import PACKET
from taf.rfrl.utilities.parsers.pcap_checker.exceptions import InspectionError


class AbstractInspector(ABC):
    """Base interface for all inspectors."""

    @abstractmethod
    def inspect(self, packet: PACKET) -> None:
        """
        Signature of inspect method which checks if given packet matches to inspector.
        If packet does not pass check it will raise InspectionError.
        """

    @abstractmethod
    def __repr__(self) -> str:
        """Signature of __repr__ method is required for pretty data presentation."""


class HasInspector(AbstractInspector):
    """Creates inspector to check if packet contain given key and value."""

    def __init__(self, key: str, value: Any = None) -> None:
        self.key = key
        self.value = value

    def inspect(self, packet: PACKET) -> None:
        """
        Checks if given key exists in packet tree and if given value of key is equal to value found in packet tree.
        """

        try:
            values = packet.get_field_value_by_name(self.key)
        except KeyError:
            raise InspectionError(f'missing "{self.key}" key')

        if self.value is not None:

            for value in values:
                if value == str(self.value):
                    break
            else:
                msg = f'expected "{self.value}" does not match to {values} value{"s" if len(values) > 1 else ""}'
                raise InspectionError(msg)

    def __repr__(self) -> str:
        """Pretty inspector presentation."""

        return f'HasInspector(key=\'{self.key}\', value=\'{self.value}\')'


class NotHasInspector(AbstractInspector):
    """Creates inspector to check if packet NOT contain given key and value."""

    def __init__(self, key: str, value: Any = None) -> None:
        self.key = key
        self.value = value

    def inspect(self, packet: PACKET) -> None:
        """
        Checks if given key exists in packet tree and if given value of key is equal to value found in packet tree.
        """

        try:
            values = packet.get_field_value_by_name(self.key)
        except KeyError:
            values = None

        if values is not None:

            if self.value is not None:

                for value in values:
                    if value == str(self.value):
                        raise InspectionError(f'Pair of "{self.key}" key and "{self.value}" value exists')

            else:
                raise InspectionError(f'"{self.key}" key exists')

    def __repr__(self) -> str:
        """Pretty inspector presentation."""

        return f'NotHasInspector(key=\'{self.key}\', value=\'{self.value}\')'


class PassesInspector(AbstractInspector):
    """Creates inspector to check if given function or keyword passes with passed packet as argument."""

    def __init__(self, callback: str) -> None:

        if isinstance(callback, str):
            fn = self._get_callback_by_name(callback)
        elif callable(callback):
            fn = callback
        else:
            raise RuntimeError('"callback" parameter should be name of keyword (string) or callable object.')

        self.callback = fn

    def inspect(self, packet: PACKET) -> None:
        """Checks if given keyword passes for given packet."""

        self.callback(packet)

    @staticmethod
    def _get_callback_by_name(callback_name: str) -> Callable:
        """
        Returns callback based on passed string.
        In Robot context it is name of keyword (python or robot) and in Python context
        it is import path to given function.
        """

        if EXECUTION_CONTEXTS.current is not None:

            def callback(packet):
                BuiltIn().run_keyword(callback_name, packet)

        else:

            import_chunks = callback_name.rsplit('.', 1)

            if len(import_chunks) != 2:
                raise ValueError('Inspector requires import string in Python context, e.g: "module.function"')

            import_path, import_name = import_chunks
            callback = getattr(__import__(import_path), import_name)

        return callback

    def __repr__(self) -> str:
        """Pretty inspector presentation."""

        return f'PassesInspector(callback=\'{self.callback}\')'
